package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BZip2CompressorInputStream.close()
 */
public class BZip2CompressorInputStream_close_TriageGen2Test {

    @Test
    public void testClose_WithNullInputStream() throws IOException {
        // Testing the case where this.in is null
        // We use reflection or a subclass to simulate this if the constructor doesn't allow it,
        // but based on the code, if in is null, it should just return.
        BZip2CompressorInputStream stream = spy(new BZip2CompressorInputStream(new java.io.ByteArrayInputStream(new byte[0])));

        // Manually setting in to null via reflection to cover the 'if (inShadow != null)' false branch
        try {
            java.lang.reflect.Field inField = BZip2CompressorInputStream.class.getDeclaredField("in");
            inField.setAccessible(true);
            inField.set(stream, null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        stream.close();
        // No exception should be thrown
    }

    @Test
    public void testClose_WithSystemIn() throws IOException {
        // Testing the case where inShadow == System.in
        // The inner if (inShadow != System.in) should be false, so close() should NOT be called on System.in
        BZip2CompressorInputStream stream = new BZip2CompressorInputStream(System.in);

        // We can't easily mock System.in, but we can verify it doesn't throw an exception
        // and that the internal state is cleared.
        stream.close();

        // Verify internal state via reflection (in and data should be null)
        java.lang.reflect.Field inField = BZip2CompressorInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        java.lang.reflect.Field dataField = BZip2CompressorInputStream.class.getDeclaredField("data");
        dataField.setAccessible(true);

        assert inField.get(stream) == null;
        assert dataField.get(stream) == null;
    }

    @Test
    public void testClose_WithNormalInputStream() throws IOException {
        // Testing the standard successful close path
        InputStream mockIn = mock(InputStream.class);
        BZip2CompressorInputStream stream = new BZip2CompressorInputStream(mockIn);

        stream.close();

        // Verify inShadow.close() was called
        verify(mockIn, times(1)).close();

        // Verify internal state is cleared
        java.lang.reflect.Field inField = BZip2CompressorInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        java.lang.reflect.Field dataField = BZip2CompressorInputStream.class.getDeclaredField("data");
        dataField.setAccessible(true);

        assert inField.get(stream) == null;
        assert dataField.get(stream) == null;
    }

    @Test
    public void testClose_WithExceptionDuringClose() throws IOException {
        // Testing the finally block: even if close() throws IOException, 
        // data and in must be set to null.
        InputStream mockIn = mock(InputStream.class);
        doThrow(new IOException("Simulated Close Failure")).when(mockIn).close();

        BZip2CompressorInputStream stream = new BZip2CompressorInputStream(mockIn);

        try {
            stream.close();
        } catch (IOException e) {
            // Expected
        }

        // Verify state is still cleared despite exception
        java.lang.reflect.Field inField = BZip2CompressorInputStream.class.getDeclaredField("in");
        inField.setAccessible(true);
        java.lang.reflect.Field dataField = BZip2CompressorInputStream.class.getDeclaredField("data");
        dataField.setAccessible(true);

        assert inField.get(stream) == null;
        assert dataField.get(stream) == null;
    }
}
